import sailpoint.object.Application;

log.warn("Fixing it...");
String APP_NAME = "My CGW";
Application fixIt = context.getObjectByName(Application.class, APP_NAME);
context.saveObject(fixIt);
context.commitTransaction();
context.decache();

log.warn("Fixed it!");
return context.getObjectByName(Application.class, APP_NAME);
